    fn next(self) -> Light {
        match self {
            Light::Red => Light::Green,
            Light::Green => Light::Yellow,
            Light::Yellow => Light::Red,
        }
    }

    fn name(&self) -> &'static str {
        match self {
            Light::Red => "Red",
            Light::Yellow => "Yellow",
            Light::Green => "Green",
        }
    }
